import heapq

def find_top_k_integers(lists, k):
    heap = []
    for lst in lists:
        for num in lst:
            heapq.heappush(heap, num)
            if len(heap) > k:
                heapq.heappop(heap)
    return [heapq.heappop(heap) for _ in range(k)]

def max_Prime_Factors(n):
    prime_factors = []
    i = 2
    while i * i <= n:
        if n % i == 0:
            prime_factors.append(i)
            n //= i
        else:
            i += 1
    if n > 1:
        prime_factors.append(n)
    return max(prime_factors)

