            stack.append(char)
        elif char == ')' or char == '}' or char == ']':
            if len(stack) == 0:
                return False
            if char == ')' and stack[-1] == '(':
                stack.pop()
            elif char == '}' and stack[-1] == '{':
                stack.pop()
            elif char == ']' and stack[-1] == '[':
                stack.pop()
            else:
                return False
    return len(stack) == 0

