def largest_palindrome(arr, n):
    max_palindrome = 0
    for i in range(n):
        for j in range(i+1, n):
            if is_palindrome(arr[i], arr[j]):
                max_palindrome = max(max_palindrome, arr[i] * arr[j])
    return max_palindrome

def is_palindrome(num1, num2):
    return str(num1) == str(num1)[::-1] and str(num2) == str(num2)[::-1]

def binomial_probability(n, k, p):
    """
    Compute the binomial probability for the given number of trials, successes, and probability of success.
    """
    return math.comb(n, k) * (p**k) * ((1-p)**(n-k))

def frequency_Of_Largest(arr):
    max_val = max(arr)
    count = 0
    for i in arr:
        if i == max_val:
            count += 1
    return count

def extract_symmetric(lst):
    result = set()
    for i in range(len(lst)):
        for j in range(i+1, len(lst)):
            if lst[i] == lst[j][::-1]:
                result.add(tuple(lst[i]))
    return result

def binary_search(arr, x):
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            return True
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return False

def binary_to_integer(binary_tuple):
    binary_str = ''.join(str(x) for x in binary_tuple)
    return int(binary_str, 2)

import re

def remove_lowercase(string):
    return re.sub(r'[a-z]', '', string)

import heapq

def heap_queue_smallest(nums, k):
    heap = []
    for num in nums:
        heapq.heappush(heap, num)
    smallest = []
    for _ in range(k):
        smallest.append(heapq.heappop(heap))
    return smallest

def gcd(a, b):
    if a == 0:
        return b
    return gcd(b % a, a)

def concatenate_elements(lst):
    result = ""
    for element in lst:
        result += element
    return result

def num_comm_div(a, b):
    for i in range(1, min(a, b) + 1):
        if a % i == 0 and b % i == 0:
            return i

def add_consecutive_nums(nums):
    result = []
    for i in range(len(nums)):
        if i == 0:
            result.append(nums[i])
        else:
            result.append(result[i-1] + nums[i])
    return result

def re_order(arr):
    non_zero = []
    for i in arr:
        if i != 0:
            non_zero.append(i)
    return non_zero + [0] * (len(arr) - len(non_zero))

def same_order(list1, list2):
    if len(list1) != len(list2):
        return False
    for i in range(len(list1)):
        if list1[i] != list2[i]:
            return False
    return True

def no_of_subsequences(arr, k):
    count = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)+1):
            product = 1
            for x in range(i, j):
                product *= arr[x]
            if product < k:
                count += 1
    return count
